            "허가 기준 임상시험 결과에서 보고된 주요 이상반응은 성기능 관련이에요. 양성 전립선 비대증 임상에서 투여 1년간 발기부전 6%(위약군 3%), 성욕 감소 4%(위약군 2%), 사정 장애 2%, 여성형 유방 1%가 나타났어요. 2년차에는 발기부전 2%, 성욕 감소 1% 미만으로 낮아지는 경향이 있었어요.\n\n남성형 탈모 임상에서는 6개월 투여 기간 동안 발기기능장애 5%(위약군 3%), 성욕 감소 2%(위약군 1%)가 보고됐어요. 이 이상반응들이 복용 중단 후에도 지속될 수 있다는 점이 허가 문서에 명시돼 있죠.\n\n시판 후 보고 자료에는 알레르기 반응(발진·두드러기·혈관부종), 우울한 기분, 탈모증(주로 체모 감소), 다모증, 고환통·고환 부기도 포함돼 있어요. 성기능 변화가 나타나면 그냥 넘기지 말고 처방받은 의사에게 알리는 게 기준이에요.",
