          content: "피나모아정은 남성형 탈모증(안드로겐탈모증) 치료에 허가된 전문의약품이에요. 대상은 만 18세 이상 41세 이하 성인 남성이에요. DHT가 줄면 모낭 위축이 멈추고, 시간이 지나면 모발이 다시 굵어져요.\n\n효과를 보려면 꾸준함이 핵심이에요. 3개월째부터 변화가 시작되고, 6개월 이후에 본격적인 발모를 체감하는 분이 많아요. 초기 탈락 현상(1~2개월)이 나타날 수 있지만 새 모발이 밀고 나오는 과정이에요.\n\n중단하면 12개월 안에 탈모가 재진행돼요. 두타스테리드로 전환하거나 미녹시딜 외용제를 병용하는 전략도 있으니, 효과가 부족하면 전문의와 상의하세요."
