            "3개월 이상 복용해야 치료 효과를 볼 수 있어요. 식약처 허가 용법에 그렇게 적혀 있거든요. 단기간 먹고 변화가 없다고 중단하면 평가 자체가 어려워져요.\n\n효과가 유지되려면 계속 복용해야 해요. 중단하면 12개월 내에 치료 효과가 사라진다고 허가 문서에 명시돼 있어요. 치료 기간과 유효성은 지속적으로 평가해야 하고, 복용 여부는 정기 진료에서 의사와 함께 결정하는 게 기준이에요.\n\n피나스테리드는 5α-환원효소를 억제해 테스토스테론이 DHT로 전환되는 걸 막는 방식으로 작용해요. DHT가 모낭을 위축시키는 주요 원인이기 때문에, 이 전환 과정을 막으면 탈모 진행이 억제돼요. 용량을 늘린다고 효과가 더 커지지 않는다는 점도 허가 문서에 명확히 적혀 있어요. 1mg이 정해진 용량이에요.\n\n짧게 문장 하나. 용량 임의 증량은 식약처 허가 범위 밖이에요.",
