          content: "백일후애액의 주성분은 미녹시딜(Minoxidil) 2%예요. 두피 혈관을 확장시켜 모낭으로 가는 혈류를 늘리고, 위축된 모낭을 다시 활성화해요. 포타슘 채널 개방을 통해 혈관 민무늬근을 이완시키는 방식이에요.\n\n동광제약에서 제조하는 액상 외용제예요. 스포이트나 스프레이를 이용해 두피에 직접 도포해요. 용매로 에탄올과 프로필렌글리콜이 포함되어 있어서, 바른 직후 약간의 따가움이나 건조감이 있을 수 있어요.\n\n낮은 농도라 5%보다 두피 자극이 적어요. 민감한 두피이거나 처음 미녹시딜을 시작하는 분, 여성 탈모에 적합한 선택이에요. 프로필렌글리콜 자극이 심하면 폼 타입으로 교체하는 것도 방법이에요."
