            "3개월은 기다려야 해요. 피나엠정 식약처 허가사항은 '일반적으로 3개월 이상 복용해야 치료 효과를 볼 수 있다'고 명시하고 있어요. 탈모는 DHT(디하이드로테스토스테론)가 모낭을 위축시키면서 진행되는데, 피나스테리드는 이 변환 효소를 차단해요. 모낭이 다시 굵은 모발을 만들기 시작하기까지 시간이 필요한 거죠. 빠른 결과를 기대하면 실망하기 쉬워요.\n\n효과 유지도 복용 지속이 전제예요. 허가 기준에 따르면 복용을 중단하면 12개월 내에 치료 효과는 사라지게 돼 있어요. '어느 정도 됐으니 끊어도 되겠지'라는 생각으로 임의 중단하면 다시 원점이 될 수 있거든요. 치료 기간과 유효성은 지속적으로 평가해야 하고, 지속 여부는 의사와 상의하는 게 기준이에요.\n\n탈모 치료는 단거리 경주가 아니에요. 모발이 두꺼워지고 볼륨이 느껴지기 시작하는 시점도 사람마다 달라서, 3개월 이후에도 꾸준히 평가하며 이어가는 구조예요. 효과 타임라인을 현실적으로 이해하고 시작하는 게 중도 포기를 막는 출발점이에요.",
