          content: "제이페시아정의 허가 적응증은 만 18~41세 성인 남성의 남성형 탈모증(안드로겐탈모증)이에요. DHT 수치를 낮춰서 위축되던 모낭이 다시 굵은 모발을 만들도록 유도해요. M자·정수리 탈모 모두에 효과가 있어요.\n\n최소 3개월은 복용해야 효과를 판단할 수 있고, 6개월 이상 지속하면 발모 효과를 기대할 수 있어요. 초기 1~2개월에 오히려 머리카락이 더 빠지는 것처럼 느껴질 수 있는데, 휴지기 모발이 성장기 모발에 밀려 나오는 정상 반응이에요.\n\n복용을 멈추면 12개월 이내에 치료 전 상태로 돌아가요. 원형탈모·여성형 탈모·출산 후 탈모·41세 초과 남성에게는 효과가 없으므로 피부과에서 정확한 진단을 먼저 받아야 해요."
