          content: "모나리드정의 주성분은 피나스테리드(Finasteride) 1mg이에요. 5α-환원효소 2형을 선택적으로 억제해서 테스토스테론이 DHT(디하이드로테스토스테론)로 바뀌는 과정을 차단해요. 혈중 DHT가 65~70% 줄어들면 줄어들던 모낭이 다시 회복기에 접어들어요.\n\n진양제약에서 정제 형태로 제조하며, 표면에 코팅 처리가 되어 있어요. 코팅이 벗겨진 상태에서 임산부 피부에 닿으면 남성 태아 생식기 발달에 이상이 생길 수 있어서, 절대 부수거나 쪼개면 안 돼요. 첨가제로는 유당수화물(부형제), 미결정셀룰로스(충전제) 등이 포함돼요.\n\n프로페시아(한국오가논)와 동일 성분·함량이에요. 제네릭이라 가격은 다르지만 생물학적 동등성 시험을 통과했기 때문에 체내 흡수와 효과는 동일해요. 외용 미녹시딜과 작용 기전이 완전히 다르므로 병용도 가능해요.",
