            "1일 1회 5mg을 식사와 관계없이 경구 복용해요. 식약처 허가사항 기준이에요. 증상이 개선되더라도 최소 6개월간 치료를 유지하는 게 허가사항 안내거든요.\n\n신부전 환자는 크레아티닌 청소율 9.0 mL/min 수준까지 용량 조절이 필요 없다고 식약처 등록 정보에 나와요. 70세 이상 고령자도 배설이 약간 감소하지만 용량을 조절할 필요는 없어요. 단, 간 기능에 이상이 있는 환자는 신중히 투여해야 한다고 별도로 적혀 있어요.\n\n정제 형태라 물과 함께 통째로 삼켜요. 코팅 상태를 유지하는 게 중요해요. 임신하거나 임신 가능성이 있는 여성이 부서진 조각을 만지면 피부를 통해 흡수돼 남성 태아 외부생식기에 영향을 줄 수 있거든요. 가정에 임신 가능성 있는 여성이 있다면 손이 닿지 않는 장소에 보관하세요.",
